@dataclass
class CommandResult:
	name: str
	command: list[str]
	exit_code: int
	stdout: str
	stderr: str
	timed_out: bool = False
	process_exit_code: int | None = None
	notes: list[str] | None = None
	godot_exit_leak_warnings: list[str] | None = None
	godot_exit_leak_report: dict[str, Any] | None = None
	gut_lifecycle_report: dict[str, Any] | None = None
	cwd: str = str(ROOT)
	duration_seconds: float = 0.0
	timeout_seconds: float | None = None
	execution: str = "subprocess"
	pid: int | None = None
	streamed_output: bool = False
	cancelled: bool = False

	def to_dict(self, max_output_chars: int = 12000) -> dict[str, Any]:
		payload = {
			"name": self.name,
			"command": self.command,
			"cwd": self.cwd,
			"exit_code": self.exit_code,
			"timed_out": self.timed_out,
			"cancelled": self.cancelled,
			"duration_seconds": round(self.duration_seconds, 3),
			"execution": self.execution,
			"stdout": trim_text(self.stdout, max_output_chars),
			"stderr": trim_text(self.stderr, max_output_chars),
		}
		if self.timeout_seconds is not None:
			payload["timeout_seconds"] = self.timeout_seconds
		if self.pid is not None:
			payload["pid"] = self.pid
		if self.streamed_output:
			payload["streamed_output"] = True
		if self.process_exit_code != None and self.process_exit_code != self.exit_code:
			payload["process_exit_code"] = self.process_exit_code
		if self.notes:
			payload["notes"] = self.notes
		if self.godot_exit_leak_warnings:
			payload["godot_exit_leak_warning_count"] = len(self.godot_exit_leak_warnings)
			payload["godot_exit_leak_warnings"] = self.godot_exit_leak_warnings[:20]
		if self.godot_exit_leak_report:
			payload["godot_exit_leak_report"] = self.godot_exit_leak_report
		if self.gut_lifecycle_report:
			payload["gut_lifecycle_report"] = self.gut_lifecycle_report
		return payload


def add_package_artifact_consumer_arguments(parser: argparse.ArgumentParser) -> None:
	"""Add coordinator-owned immutable package artifact inputs to one command."""
	parser.add_argument(
		"--package-artifact-manifest",
		default="",
		help=argparse.SUPPRESS,
	)
	parser.add_argument(
		"--package-artifact-manifest-sha256",
		default="",
		help=argparse.SUPPRESS,
	)


