def collect_package_manifest_paths() -> dict[str, Any]:
	tracked_paths_result = read_git_paths(["ls-files", "-z", "--cached"])
	untracked_paths_result = read_git_paths(["ls-files", "-z", "--others", "--exclude-standard"])
	errors: list[dict[str, Any]] = []
